from rdkit import Chem
import numpy as np
from scipy.spatial.distance import pdist,squareform
m=Chem.MolFromMolFile('connected.mol',removeHs=False)
x=np.load('coordinates.npy')
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
 if m.GetAtomWithIdx(i).GetAtomicNum()>1 and m.GetAtomWithIdx(j).GetAtomicNum()>1:print(i,j,m.GetAtomWithIdx(i).GetSymbol(),m.GetAtomWithIdx(j).GetSymbol(),str(b.GetBondType()),round(np.linalg.norm(x[i]-x[j]),3))
print('minimum distance',pdist(x).min())
import matplotlib;matplotlib.use('Agg')
import matplotlib.pyplot as plt
fig=plt.figure(figsize=(10,7));ax=fig.add_subplot(111,projection='3d')
cols={'C':'#444444','H':'#DDDDDD','N':'blue','O':'red','Si':'orange','Fe':'brown'}
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx();p=x[[i,j]]
 ax.plot(*p.T,color='gray',linewidth=1.4)
for a in m.GetAtoms():
 i=a.GetIdx();sym=a.GetSymbol()
 ax.scatter(*x[i],s=120 if sym=='Fe' else 70 if sym!='H' else 12,color=cols[sym])
 if sym!='H':ax.text(*x[i],sym+str(i),fontsize=8)
ax.view_init(elev=15,azim=35);ax.set_box_aspect((1,1,1));plt.tight_layout();plt.savefig('structure.png',dpi=160)
